import { EmailMessage } from "cloudflare:email";

export default {
  async email(message: ForwardableEmailMessage, env: Env): Promise<void> {
    const raw = await new Response(message.raw).arrayBuffer();
    const parsed = await extractInvoiceFromEmail(raw, env.AI);
    await appendToSheets(parsed, env.SHEETS_TOKEN);
  }
};

import { chromium } from "playwright";

export async function scrapePricing(url: string) {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.goto(url, { waitUntil: "networkidle" });
  const text = await page.innerText("body");
  await browser.close();
  return text;
}

async function generateWeeklyDigest(env) {
  const metrics = await gatherMetrics(env);
  const draft = await env.AI.run("@cf/meta/llama-3-8b-instruct", {
    prompt: `Generate concise executive digest from metrics: ${JSON.stringify(metrics)}`
  });
  return draft;
}

